#include <stdio.h>

int main() {
    int a[] = {1, 4, 0, 2};
    int n = 4;
    int result = n;
    for (int i = 0; i < n; i++) {
        result ^= i ^ a[i];
    }
    printf("%d\n", result);
    return 0;
}
